def seed(apps: Apps, schema_editor: BaseDatabaseSchemaEditor | None) -> None:
    """Create the three rows (skipping a slug already there, so running it twice is harmless)."""
    service = apps.get_model("content", "Service")
    for row in SERVICES:
        if not service.objects.filter(slug=row["slug"]).exists():
            service.objects.create(**row)
    slugs = [row["slug"] for row in SERVICES]
    service.objects.filter(slug__in=slugs).update(updated_at=UPDATED_ON)  # bypasses auto_now


def unseed(apps: Apps, schema_editor: BaseDatabaseSchemaEditor | None) -> None:
    apps.get_model("content", "Service").objects.filter(
        slug__in=[row["slug"] for row in SERVICES]
    ).delete()


